"""Original questions grounded in the school materials supplied 17 October 2026."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
questions=[]
STRATEGY='Answer the command word. Give distinct scientific points and link each adaptation to its benefit. For calculations, show working and units.'
def point(label,*groups,allow_negative=False):
    return dict(label=label,allOf=list(groups),allowNegative=allow_negative)
def add(topic,prompt,points,hint,difficulty=2,diagram=None,model=None):
    i=len(questions)+1
    q=dict(id=f'bio-nov2-20261017-{i:03}',conceptId=f'bio-nov2-20261017-{i:03}',assessmentId='biology-nov2',subject='biology',year=9,topic=topic,difficulty=difficulty,format='typed_rubric',marks=len(points),prompt=prompt,answer=dict(mode='biology_rubric',accepted=[model or ' '.join(p['label'] for p in points)],points=points),modelAnswer=model or ' '.join(p['label'] for p in points),markKeywords=[p['label'] for p in points],hint=hint,examGuidance=dict(strategy=STRATEGY,commonError=hint),source='School materials supplied 17 October 2026; original GCSE AQA-style question, not an official AQA question.')
    if diagram:q.update(diagram=diagram,diagramAlt='Drawing A uses single outlines and straight label lines; drawing B uses sketchy shaded lines and crossing label lines.')
    questions.append(q)

T='Cell structures in context'
add(T,'An onion epidermal cell has a nucleus. State two functions of the nucleus.',[point('The nucleus contains genetic material / DNA.','(genetic|dna|chromosom)'),point('It controls cell activities.','control|regulat','activit|function|process')],'Name a function, rather than just saying it is important.',1)
add(T,'Explain why cells that need a lot of energy often contain many mitochondria.',[point('Mitochondria are the site of aerobic respiration.','mitochondri|they','aerobic respir'),point('Respiration releases energy for cell processes.','releas','energy')],'Write releases energy, rather than creates energy.')
add(T,'State the function of the cell membrane.',[point('It controls movement of substances into and out of the cell.','control|regulat|selectiv','(enter|leav|movement|pass|in and out|into|out of)')],'Do not confuse a cell membrane with a cellulose cell wall.',1)
add(T,'State the function of the cellulose cell wall in an onion cell.',[point('It supports and strengthens the cell.','support|strength|rigid')],'The wall supports the cell; the membrane controls movement.',1)
add(T,'Name the cell structure where proteins are synthesised.',[point('Ribosomes.','\\bribosomes?\\b')],'Use the organelle name.',1)
add(T,'An onion bulb cell has no chloroplasts. Explain why.',[point('The bulb grows underground and receives little or no light.','underground|below ground|little light|no light|dark',allow_negative=True),point('The cell does not carry out photosynthesis.','(not|no|cannot|doesn.t|can.t|lack).{0,35}photosynth|photosynth.{0,20}(not|no|unnecessary)',allow_negative=True)],'The question refers to the bulb, not a green onion leaf.')
add(T,'Name two structures present in a typical plant cell but absent from a typical animal cell.',[dict(label='One valid structure: cellulose cell wall, chloroplast or permanent vacuole.',distinctPool='plant'),dict(label='A second different structure from the same list.',distinctPool='plant')],'Choose two different structures: cellulose wall, chloroplasts or a large permanent vacuole.',1,model='Cellulose cell wall and chloroplasts.')
add(T,'Explain why a mature mammalian red blood cell is different from a typical animal cell.',[point('It has no nucleus.','(no|without|lack|absen).{0,25}nucle|nucle.{0,20}(absen|lost)',allow_negative=True),point('This leaves more space for haemoglobin.','(more|extra|greater).{0,25}(space|room)|space.{0,20}(more|extra)','ha?emoglobin')],'Specify haemoglobin rather than just saying more room for oxygen.')

T='Specialised animal cells'
add(T,'State the function of a sperm cell.',[point('It fertilises an egg by carrying male genetic material to it.','fertilis|fertiliz|male.{0,20}(genetic|dna).{0,30}egg')],'Describe its biological job.',1)
add(T,'Explain two adaptations that help a sperm cell swim towards an egg.',[point('A flagellum / tail propels the sperm.','flagell|tail','propel|swim|mov'),point('Many mitochondria release energy by respiration for movement.','mitochondri','energy|respir','mov|swim|tail|flagell')],'Link each named structure to swimming; acrosome enzymes help entry into the egg.')
add(T,'Explain how the acrosome helps a sperm cell fertilise an egg.',[point('The acrosome contains enzymes.','enzym'),point('The enzymes digest the outer layers surrounding the egg.','digest|break down|penetrat','egg|outer|layer|coat')],'Do not say the acrosome provides the energy for swimming.')
add(T,'How many chromosomes are in a normal human sperm nucleus, and why is this useful at fertilisation?',[point('It has 23 chromosomes / one haploid set.','\\b23\\b|haploid|one set|single set'),point('Combining with the egg restores the normal chromosome number.','restor|46|diploid|two sets|normal number')],'Do not give the 46 chromosomes of a typical body cell.')
add(T,'Explain how the long axon of a neurone helps its function.',[point('It carries electrical impulses.','electrical|nerve','impuls|signal'),point('The axon allows transmission over long distances.','long|distant','distanc|body|arm|leg')],'Call the signal an electrical impulse, not a flow of blood.')
add(T,'Explain the benefit of the myelin sheath around an axon.',[point('It electrically insulates the axon.','insulat'),point('It increases the speed of impulse transmission.','fast|speed|quick','impuls|signal|transmi')],'Insulation and faster transmission are two distinct points.')
add(T,'Explain why neurones have branched connections.',[point('Branches connect to other cells / neurones.','connect|link','cell|neuron|neuron'),point('This allows communication with several other cells.','many|several|multiple|network','cell|neuron|communicat|connect')],'Make the link between branching and a network of connections.')
add(T,'Describe how a muscle cell contracts.',[point('It contains contractile protein filaments.','protein|filament|actin|myosin'),point('The filaments slide past each other, shortening the cell.','slid','short|contract')],'The filaments slide; do not say the proteins themselves shrink.')
add(T,'Explain why muscle cells have many mitochondria.',[point('Mitochondria release energy by respiration.','mitochondri','respir|energy'),point('The energy is needed for muscle contraction.','energy','contract|shorten')],'Name contraction, rather than saying the muscle needs power.')
add(T,'Distinguish the functions of skeletal muscle and smooth muscle.',[point('Skeletal muscle contracts to move bones.','skeletal','bone|skeleton'),point('Smooth muscle contracts in walls of organs such as the gut.','smooth','organ|gut|intestin|vessel|stomach')],'Smooth muscle does not attach directly to bones.')
add(T,'State what haemoglobin does in a red blood cell.',[point('Haemoglobin binds oxygen for transport.','oxygen','bind|carr|transport')],'Oxygen is transported bound to haemoglobin.',1)
add(T,'Explain how the biconcave shape of a red blood cell helps oxygen exchange.',[point('It gives a large surface area relative to volume.','large|increas|greater','surface area'),point('It provides a short diffusion distance / rapid diffusion of oxygen.','short.{0,20}(distanc|path)|fast.{0,20}diffus|rapid.{0,20}diffus|quicker.{0,20}diffus')],'Link shape to surface area or diffusion, not just to fitting in blood.')
add(T,'Explain why a red blood cell is flexible.',[point('It can change shape / deform.','chang.{0,10}shape|deform|bend|flex'),point('This lets it pass through narrow capillaries.','narrow|small|tiny','capillar|vessel')],'Name the narrow blood vessels: capillaries.')
add(T,'Explain how ciliated epithelial cells help protect the airways.',[point('Cilia beat to move mucus towards the throat.','cilia','beat|waft|mov','mucus'),point('The mucus carries trapped particles or pathogens away from the lungs.','trap|remov|carr','particl|pathogen|bacter|dust|microb')],'Cilia move mucus; goblet cells mainly secrete it.')
add(T,'Distinguish the roles of goblet cells and ciliated cells in the airways.',[point('Goblet cells secrete mucus.','goblet','secret|produc|make','mucus'),point('Ciliated cells beat their cilia to move mucus.','ciliat|cilia','mov|beat|waft','mucus')],'Do not say cilia produce the mucus.')
add(T,'A cell has a long myelinated axon and branched endings. Identify the cell and explain its function.',[point('It is a neurone / nerve cell.','neuron|neurone|nerve cell'),point('It carries electrical impulses over long distances.','electrical|nerve','impuls|signal','long|distanc')],'Use evidence from its structure to identify it.')

T='Specialised plant cells'
add(T,'Explain how the shape of a root hair cell helps absorption.',[point('The long hair-like projection increases surface area.','hair|project|extension','surface area'),point('A larger surface area allows greater absorption of water and mineral ions.','water','mineral|ion','absorb|absorp|uptake')],'Name the long projection and the substances absorbed.')
add(T,'State how water enters a root hair cell.',[point('By osmosis.','\\bosmosis\\b')],'Osmosis describes water movement, not mineral-ion uptake.',1)
add(T,'Mineral ions move into a root hair cell against their concentration gradient. Name the process and explain the need for mitochondria.',[point('The process is active transport.','active transport'),point('Mitochondria release energy by respiration for active transport.','mitochondri','energy|respir')],'Do not describe mineral-ion uptake as osmosis.')
add(T,'Explain why root hair cells usually do not have chloroplasts.',[point('They are underground and receive little or no light.','underground|below ground|little light|no light',allow_negative=True),point('They do not photosynthesise.','(not|cannot|no|doesn.t|can.t).{0,20}photosynth',allow_negative=True)],'They absorb materials; they do not photosynthesise underground.')
add(T,'State two functions of xylem tissue.',[point('It transports water and mineral ions.','water','mineral|ion'),point('It supports the plant.','support|strength')],'Xylem does not transport dissolved sugars.',1)
add(T,'Explain why mature xylem vessels are hollow and have no end walls.',[point('There is no cytoplasm to obstruct water flow.','no|without|lack|absen','cytoplasm|obstruct',allow_negative=True),point('Absent end walls form a continuous tube for water flow.','end wall|continuous tube','flow|water|continu',allow_negative=True)],'Explain the benefit to flow rather than listing dead cells.')
add(T,'Explain the role of lignin in xylem vessels.',[point('Lignin strengthens the vessel walls.','lignin|it','strength|reinforc'),point('The strengthened walls help prevent collapse.','prevent|resist|stop','collaps')],'Waterproofing is also useful, but this question asks how lignin supports a vessel.')
add(T,'State the main substances transported by phloem and name the transport process.',[point('Dissolved sugars / sucrose.','sugar|sucrose'),point('Translocation.','translocation')],'Use dissolved sugars rather than the vague word food.',1)
add(T,'Describe the direction of transport in xylem and phloem.',[point('Xylem carries water upwards from the roots.','xylem','up|root.{0,15}lea'),point('Phloem transports sugars from source to sink, upwards or downwards in different tubes.','phloem','source.{0,15}sink|up.{0,20}down|both direction')],'Phloem does not carry sugars simultaneously in opposite directions in the same tube.')
add(T,'Explain how sieve plates help phloem function.',[point('The plates contain pores / holes.','pore|hole|perforat'),point('The pores allow sugar solution to flow between sieve tube elements.','sugar|sucrose|solution','flow|pass|mov')],'Name what moves through the pores.')
add(T,'Explain why phloem companion cells have many mitochondria.',[point('Mitochondria release energy by respiration.','mitochondri','energy|respir'),point('Energy is used for active loading / transport of sugars.','active|loading','sugar|sucrose|transport')],'Link energy to sugar loading, not to photosynthesis.')
add(T,'Compare the conducting cells in mature xylem and phloem.',[point('Mature xylem vessel elements are dead.','xylem','dead|not living',allow_negative=True),point('Phloem sieve tube elements are living.','phloem|sieve','living|alive')],'A comparison must refer to both tissues.')

T='Microscopy practical'
add(T,'Explain why onion epidermis should be peeled as a thin single layer.',[point('A thin layer allows light to pass through.','light','pass|transmi|through'),point('A single layer reduces overlapping cells.','overlap','reduc|avoid|prevent|less|no|not',allow_negative=True)],'Connect the thin specimen to visibility.')
add(T,'Name the stain used for an onion epidermis slide and explain why it is used.',[point('Iodine solution.','iodine'),point('Staining improves contrast so cell structures are easier to see.','contrast|easier.{0,15}(see|distinguish)|clearer|visible')],'The purpose is improved contrast, not magnifying the cells.')
add(T,'Name a stain commonly used for cheek cells and state its purpose.',[point('Methylene blue.','methylene blue'),point('It increases contrast so cell structures can be distinguished.','contrast|easier.{0,15}(see|distinguish)|clearer|visible')],'Iodine is the stain used in the onion method.')
add(T,'Explain how to lower a coverslip and why this is important.',[point('Lower it gently at an angle using a mounted needle.','angle|slant','lower|gentl|needle'),point('This reduces trapped air bubbles.','air|bubble','reduc|avoid|prevent|less|stop')],'Air bubbles may look like dark rings and obscure cells.')
add(T,'Why should you start viewing a slide with the lowest-power objective?',[point('It gives a larger field of view.','large|wide','field of view'),point('This makes the specimen easier to locate.','easier|easy|locat|find','specimen|cell|sample')],'The image is smaller but the visible area is larger.')
add(T,'Explain why the specimen should be centred before changing to a higher-power objective.',[point('Higher power gives a smaller field of view.','small|narrow|reduc','field of view'),point('Centring helps keep the specimen visible.','centre|center|keep|remain','visible|view|sight')],'Otherwise the cell may move outside the visible area.')
add(T,'Which focusing control should be used for small adjustments at high power? Explain one benefit.',[point('Use the fine-focus control.','fine.{0,12}(focus|adjust)'),point('Small adjustments help avoid driving the objective into the slide.','small|gentle|avoid|prevent','adjust|collis|break|crash|slide|damage')],'Do not use large coarse-focus movements at high power.')
add(T,'Describe four steps in preparing an onion epidermis slide.',[point('Peel a thin layer of epidermis with forceps.','peel|remov','thin|single|epiderm'),point('Place it flat on a clean slide in a drop of water.','slide','water'),point('Add iodine solution.','iodine'),point('Lower a coverslip gently at an angle.','coverslip|cover slip','angle|slant')],'Give the method in a logical order; include the stain and coverslip.',3)
add(T,'A slide has many dark circular rings. Suggest what they are and how to reduce them when preparing another slide.',[point('The rings may be trapped air bubbles.','air bubble|bubbles'),point('Lower the coverslip at an angle.','coverslip|cover slip','angle|slant')],'Do not automatically label a dark ring as a nucleus.')
add(T,'State one risk when using glass slides and one suitable precaution.',[point('Broken glass can cut skin.','glass','cut|sharp|break|broken'),point('Handle slides carefully and report breakages / dispose of broken glass safely.','careful|report|safe|dispos','slide|glass|break')],'Pair the precaution with the stated hazard.')
add(T,'State the roles of the stage and the objective lens.',[point('The stage supports the slide.','stage','support|hold'),point('The objective lens magnifies the specimen.','objective','magnif|enlarg')],'The eyepiece is another lens, not the stage.')
add(T,'A microscope image is dark. Suggest two checks before preparing a new slide.',[point('Check or adjust the light / illumination.','light|illuminat|lamp|mirror'),point('Check that the specimen is positioned over the light opening.','position|centre|center|over','specimen|slide|light|opening')],'A visibility problem does not always mean the specimen is damaged.')
add(T,'Explain why you should not draw chloroplasts in a biological drawing of onion bulb epidermis.',[point('Onion bulb epidermal cells usually have no chloroplasts.','(no|lack|without|not|absen).{0,30}chloroplast',allow_negative=True),point('A biological drawing should show only structures actually observed.','observ|seen|visible','only|actual|draw')],'Draw the observation rather than a memorised typical plant cell.')
add(T,'A routine classroom light-microscope preparation does not show ribosomes. Explain why.',[point('Ribosomes are extremely small / below the microscope resolution limit.','small|resolution|resolv'),point('Magnifying the image further cannot reveal details that were not resolved.','magnif|enlarg','not|cannot|can.t|doesn.t','detail|resolv|clear',allow_negative=True)],'Resolution determines detail; magnification alone makes the image larger.',3)

T='Biological drawing'
add(T,'State two rules for the outlines in a biological drawing.',[point('Use clear single lines.','single|clear|clean','line'),point('Do not shade the drawing.','(no|not|avoid|without).{0,15}shad|unshaded',allow_negative=True)],'Avoid repeated sketch lines and artistic shading.',1)
add(T,'State two rules for label lines in a biological drawing.',[point('Draw straight label lines in pencil.','straight','line'),point('Label lines must not cross.','(not|no|avoid|without).{0,15}(cross|overlap)|uncross',allow_negative=True)],'Keep labels readable and point precisely to the structure.',1)
add(T,'According to your school checklist, state three presentation requirements for a biological drawing apart from labels.',[point('A clear underlined title.','title','underlin'),point('The magnification.','magnification|magnif'),point('The drawing occupies at least half the page.','half','page')],'This question follows your school practical rubric.',1)
add(T,'A student copies a textbook plant cell and adds chloroplasts that were not seen. Explain why this is poor biological drawing.',[point('The drawing must represent what was actually observed.','observ|seen|visible','actual|draw|only'),point('Structures not observed should not be added.','(not|no|avoid).{0,45}(add|draw)|invent|made.up',allow_negative=True)],'A biological drawing records evidence, not an idealised cell.')
add(T,'Compare magnification and resolution.',[point('Magnification is how many times larger an image is than the actual object.','magnif','larg|enlarg|size'),point('Resolution is the ability to distinguish close points as separate.','resolution|resolv','separat|distinguish','point|structure|object')],'Bigger does not automatically mean more detail.')
add(T,'Explain why a scale bar is useful when a cell image is resized.',[point('The scale bar resizes with the image.','scale bar','resiz|enlarg|reduc|chang'),point('It still allows actual sizes to be calculated correctly.','actual|real','size|length','calculat|correct|measur')],'A printed magnification number may become wrong after resizing.')
add(T,'A student doubles the printed width of a micrograph labelled x200 but keeps the label x200. State the new magnification and explain the problem.',[point('The new magnification is x400.','400\\b'),point('The original magnification label is no longer valid after enlargement.','label|200|original','wrong|incorrect|invalid|not|chang|no longer valid',allow_negative=True)],'Image size changed, so the magnification changed.',3)
add(T,'Explain why an electron microscope can reveal finer cell detail than a light microscope.',[point('It has greater resolving power / resolution.','greater|higher|better','resolv|resolution'),point('It can distinguish smaller structures / closer points as separate.','small|close|fine','structur|point|detail','separat|distinguish|see|reveal')],'Higher magnification alone is not a full explanation.')
add(T,'Drawing A has single outlines and straight uncrossed labels. Drawing B has sketchy shaded outlines and crossing labels. Identify the better drawing and give two reasons.',[point('Drawing A is better.','drawing a|\\ba\\b'),point('It uses clear single outlines without shading.','single|clear|unshaded','outline|line'),point('Its label lines do not cross.','label','not.{0,10}cross|uncross|no.{0,10}cross',allow_negative=True)],'Name the drawing, then refer to two visible drawing conventions.',2,'biology-nov2-drawing.svg')
add(T,'Your school drawing rubric includes two calculations. Name them.',[point('Width / diameter of the field of view.','field of view','width|diameter'),point('Length / size of one cell.','cell','length|size')],'A magnification label alone does not supply these calculations.',1)

T='Microscopy calculations'
def calc(prompt,value,unit,working,method,explanation,difficulty=2):
    points=[point('Use the correct relationship and substitute compatible units.',*method)]
    points.append(dict(label=f'Correct final answer: {value:g} {unit or "(magnification, no unit)"}.',numericResult=True))
    if unit:points.append(dict(label=f'Give the final size in {unit}.',numericUnit=True))
    add(T,prompt,points,explanation,difficulty,model=working)
    questions[-1]['answer']['numeric']=dict(value=value,unit=unit,tolerance=max(abs(value)*1e-5,1e-10))
    questions[-1]['workedSolution']=working

for ey,ob in [(10,4),(10,40),(15,20),(10,50)]:
    calc(f'A microscope has an eyepiece magnification of x{ey} and an objective magnification of x{ob}. Calculate the total magnification.',ey*ob,'',f'Total magnification = {ey} x {ob} = x{ey*ob}.',[f'{ey}\\s*[x×*]\\s*{ob}|{ob}\\s*[x×*]\\s*{ey}|eyepiece.{{0,20}}objective'],'Multiply the two lens magnifications. Magnification has no unit.',1)
for image,actual in [(8,20),(18,45),(12,30),(6,15)]:
    v=image*1000/actual
    calc(f'A cell image is {image} mm long. Its actual length is {actual} µm. Calculate magnification. Show working.',v,'',f'{image} mm = {image*1000} µm. M = {image*1000} / {actual} = x{v:g}.',[f'{image*1000}|image.{{0,15}}(actual|real)|{image}\\s*/\\s*0\\.0'],'Convert image and actual size to the same unit before dividing.')
for image,mag in [(5,1000),(19.5,1500),(24,600),(9,300)]:
    v=image/mag*1000
    calc(f'A cell image measures {image} mm at x{mag}. Calculate its actual length in µm. Show working.',v,'µm',f'Actual length = {image} / {mag} = {image/mag:g} mm. Multiply by 1000: {v:g} µm.',[f'{image}\\s*[/÷]\\s*{mag}|image.{{0,20}}magnif'],'Actual size = image size / magnification. Convert mm to µm by multiplying by 1000.')
for actual,mag in [(0.01,2500),(0.08,400),(0.02,1500),(0.005,2000)]:
    v=actual*mag
    calc(f'A real cell is {actual} mm long. Calculate the drawing length in mm at x{mag}. Show working.',v,'mm',f'Image length = actual length x magnification = {actual} x {mag} = {v:g} mm.',[f'{actual}\\s*[x×*]\\s*{mag}|{mag}\\s*[x×*]\\s*{actual}|actual.{{0,20}}magnif'],'Image size = magnification x actual size. Both lengths here use mm.')
for fov,m1,m2,n in [(1.6,100,400,10),(1.8,100,300,6),(2,100,500,8),(2.4,100,400,12)]:
    new=fov*m1/m2;v=new/n*1000
    calc(f'The field-of-view diameter is {fov} mm at x{m1}. At x{m2}, {n} cell lengths span the diameter. Estimate one cell length in µm. Show working.',v,'µm',f'New field of view = {fov} x {m1} / {m2} = {new:g} mm. Cell length = {new:g} / {n} = {new/n:g} mm = {v:g} µm.',[f'{new:g}\\s*(mm|[/÷])|{fov}\\s*[x×*]\\s*{m1}'],'First adjust the field of view for the new magnification, then divide by the cell count.',3)
for div,cal in [(5,0.01),(8,0.005)]:
    v=div*cal*1000
    calc(f'A calibrated micrometer division represents {cal} mm. A cell spans {div} divisions. Calculate its length in µm.',v,'µm',f'Length = {div} x {cal} = {div*cal:g} mm = {v:g} µm.',[f'{div}\\s*[x×*]\\s*{cal}|{cal}\\s*[x×*]\\s*{div}'],'Multiply the number of divisions by the calibrated size of one division.')
for image,bar,real in [(12,20,50),(18,30,100)]:
    v=image/bar*real
    calc(f'On the same printed image, a cell measures {image} mm and a scale bar measures {bar} mm. The bar represents {real} µm. Calculate the actual cell length in µm.',v,'µm',f'Actual cell length = {image} / {bar} x {real} = {v:g} µm.',[f'{image}\\s*[/÷]\\s*{bar}|{image/bar:g}'],'Compare the cell and scale bar using the same printed measurement unit.',3)

bank=dict(id='biology-nov2',subject='biology',title='2 November assessment · Specialised cells and RP1',assessmentDate='2026-11-02',version='20261017-1',sourceNote='Original GCSE AQA-style questions based on the specialised-cell posters, Required Practical 1 student slides and WTO reviewing RP1 slides supplied 17 October 2026. School drawing criteria retained. Not the teacher’s actual test or official AQA questions. Roadmap-only topics, culturing microorganisms and detailed differentiation are excluded.',sources=['Adaptations of Specialised Cells Information Posters.pdf','required practical 1 - student(1).pptx','WTO reviewing RP1.pptx','Bio Teaching Materials 17OCT.docx'],corrections=['Smooth muscle acts in organ walls; skeletal muscle moves bones.','Cilia move mucus; goblet cells mainly secrete it.','19.5 mm / 1500 = 0.013 mm = 13 µm.','Resolution limits detail; magnification alone cannot resolve ribosomes.'],questions=questions)
(ROOT/'assessment/biology-nov2-20261017.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n')
